import type { Feature, FeatureCollection, MultiPolygon, Polygon, Position } from 'geojson'

/** `lat`/`lng` is a point guaranteed to be inside the footprint, used to place drops. */
export type BuildingProps = { num: string; name: string; lat: number; lng: number }
export type Building = Feature<Polygon | MultiPolygon, BuildingProps>

let buildingsPromise: Promise<Building[]> | null = null

/** Static file generated by `npm run fetch-buildings`; loaded once and cached. */
export function loadBuildings() {
  buildingsPromise ??= fetch('/data/buildings.geojson')
    .then((res) => {
      if (!res.ok) throw new Error(`Couldn't load buildings (${res.status})`)
      return res.json() as Promise<FeatureCollection<Polygon | MultiPolygon, BuildingProps>>
    })
    .then((collection) => collection.features)
  return buildingsPromise
}

function inRing([x, y]: Position, ring: Position[]) {
  let inside = false
  for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
    const [xi, yi] = ring[i]
    const [xj, yj] = ring[j]
    if (yi > y !== yj > y && x < ((xj - xi) * (y - yi)) / (yj - yi) + xi) inside = !inside
  }
  return inside
}

function inPolygon(point: Position, [outer, ...holes]: Position[][]) {
  return inRing(point, outer) && !holes.some((hole) => inRing(point, hole))
}

export function findBuildingAt(buildings: Building[], lat: number, lng: number) {
  const point = [lng, lat]
  return buildings.find(({ geometry }) =>
    geometry.type === 'Polygon' ? inPolygon(point, geometry.coordinates) : geometry.coordinates.some((poly) => inPolygon(point, poly)),
  )
}
